"""Cross-artifact validation for character-pack authoring."""

from __future__ import annotations

import hashlib
import json
import unicodedata
from collections.abc import Mapping
from typing import Any

from kokoroarc import __version__
from kokoroarc.schemas import SchemaRegistry


_FIRST_CLASS_LOCALES = ("zh-CN", "en-US", "ja-JP")
_ORIGINAL_CLAIM_SOURCES = frozenset({"creative_brief", "user_override"})
_DOSSIER_CLAIM_SOURCES = frozenset(
    {"user_dossier", "creative_brief", "user_override"}
)
_MAX_FINDINGS = 256


def validate_authoring_pack(
    request: dict[str, Any],
    source: dict[str, Any],
    schemas: SchemaRegistry,
) -> dict[str, Any]:
    """Return a deterministic cross-artifact authoring validation report."""
    hard_failures: list[dict[str, Any]] = []
    advisory_findings: list[dict[str, Any]] = []

    if source.get("character_id") != request.get("character_id"):
        hard_failures.append(
            _finding(
                "AUTHORING_IDENTITY_MISMATCH",
                ["character_id"],
                "Source character ID does not match the build request.",
            )
        )
    if source.get("character_version") != request.get("character_version"):
        hard_failures.append(
            _finding(
                "AUTHORING_VERSION_MISMATCH",
                ["character_version"],
                "Source character version does not match the build request.",
            )
        )
    if source.get("namespace") != request.get("namespace"):
        hard_failures.append(
            _finding(
                "AUTHORING_NAMESPACE_MISMATCH",
                ["namespace"],
                "Source namespace does not match the build request.",
            )
        )
    identity_value = source.get("identity")
    identity = identity_value if isinstance(identity_value, Mapping) else {}
    if identity.get("display_name") != request.get("display_name"):
        hard_failures.append(
            _finding(
                "AUTHORING_DISPLAY_NAME_MISMATCH",
                ["identity", "display_name"],
                "Source display name does not match the build request.",
            )
        )

    evidence = source.get("evidence")
    evidence_map = evidence if isinstance(evidence, Mapping) else {}
    claims_value = evidence_map.get("claims")
    claims = claims_value if isinstance(claims_value, list) else []

    mode = request.get("mode")
    if mode == "original":
        _validate_original_provenance(evidence_map, claims, hard_failures)
    elif mode == "dossier":
        _validate_dossier_provenance(
            request, source, evidence_map, claims, hard_failures
        )
    else:
        hard_failures.append(
            _finding(
                "AUTHORING_MODE_UNSUPPORTED",
                ["mode"],
                "Construction mode is not available in this milestone.",
            )
        )

    locales_value = source.get("locales")
    locales = locales_value if isinstance(locales_value, Mapping) else {}
    expressions_value = source.get("expressions")
    expressions = (
        expressions_value if isinstance(expressions_value, Mapping) else {}
    )
    locale_coverage = {
        locale: locale in locales
        and bool(expressions)
        and all(
            isinstance(locale_set, Mapping) and locale in locale_set
            for locale_set in expressions.values()
        )
        for locale in _FIRST_CLASS_LOCALES
    }
    for locale, covered in locale_coverage.items():
        if not covered:
            path = (
                ["locales", locale]
                if locale not in locales
                else ["expressions", locale]
            )
            hard_failures.append(
                _finding(
                    "AUTHORING_LOCALE_MISSING",
                    path,
                    f"Source pack does not provide the {locale} locale.",
                )
            )

    if len(expressions) < 2:
        advisory_findings.append(
            _finding(
                "AUTHORING_SPARSE_EXAMPLES",
                ["expressions"],
                "More expression examples would improve coverage.",
            )
        )

    hard_failures.sort(key=_finding_sort_key)
    advisory_findings.sort(key=_finding_sort_key)
    hard_failures = hard_failures[:_MAX_FINDINGS]
    advisory_findings = advisory_findings[:_MAX_FINDINGS]
    report = {
        "schema_version": "1.0",
        "artifact_id": _report_artifact_id(request),
        "created_by": {"component": "kokoroarc", "version": __version__},
        "hard_failures": hard_failures,
        "advisory_findings": advisory_findings,
        "locale_coverage": locale_coverage,
        "provenance_counts": {
            "evidence": len(claims),
            "derived_profile": _mapping_count(
                source.get("derived_profile"), "traits"
            ),
            "user_override": _mapping_count(source.get("overrides"), "values"),
        },
        "valid": not hard_failures,
    }
    schemas.validate("build-validation-report", report)
    return report


def _validate_original_provenance(
    evidence: Mapping[str, Any],
    claims: list[Any],
    findings: list[dict[str, Any]],
) -> None:
    if evidence.get("authored_original") is not True:
        findings.append(
            _finding(
                "AUTHORING_ORIGINAL_EVIDENCE_REQUIRED",
                ["evidence", "authored_original"],
                "Original mode requires explicitly authored-original evidence.",
            )
        )
    for index, claim in enumerate(claims):
        source = claim.get("source") if isinstance(claim, Mapping) else None
        if _normalize_source_label(source) not in _ORIGINAL_CLAIM_SOURCES:
            findings.append(
                _finding(
                    "AUTHORING_EXTERNAL_CANON_PROHIBITED",
                    ["evidence", "claims", index, "source"]
                    if isinstance(claim, Mapping)
                    else ["evidence", "claims", index],
                    "Original mode cannot present a claim as external canon.",
                )
            )


def _validate_dossier_provenance(
    request: Mapping[str, Any],
    source: Mapping[str, Any],
    evidence: Mapping[str, Any],
    claims: list[Any],
    findings: list[dict[str, Any]],
) -> None:
    inputs_value = request.get("inputs")
    inputs = inputs_value if isinstance(inputs_value, list) else []
    has_dossier_input = any(
        isinstance(item, Mapping) and item.get("type") == "user_dossier"
        for item in inputs
    )
    dossier_claims = [
        claim
        for claim in claims
        if isinstance(claim, Mapping)
        and _normalize_source_label(claim.get("source")) == "user_dossier"
        and isinstance(claim.get("statement"), str)
    ]
    if evidence.get("authored_original") is True:
        findings.append(
            _finding(
                "AUTHORING_DOSSIER_ORIGINAL_PROVENANCE_PROHIBITED",
                ["evidence", "authored_original"],
                "Dossier mode cannot be marked as authored original.",
            )
        )
    for index, claim in enumerate(claims):
        source_label = (
            _normalize_source_label(claim.get("source"))
            if isinstance(claim, Mapping)
            else None
        )
        if source_label not in _DOSSIER_CLAIM_SOURCES:
            findings.append(
                _finding(
                    "AUTHORING_DOSSIER_CANON_PROHIBITED",
                    ["evidence", "claims", index, "source"]
                    if isinstance(claim, Mapping)
                    else ["evidence", "claims", index],
                    "Dossier mode cannot relabel user assertions as canon.",
                )
            )
    if not has_dossier_input:
        findings.append(
            _finding(
                "AUTHORING_DOSSIER_EVIDENCE_REQUIRED",
                ["inputs"],
                "Dossier mode requires a typed user-dossier input.",
            )
        )
    elif not dossier_claims:
        findings.append(
            _finding(
                "AUTHORING_DOSSIER_EVIDENCE_REQUIRED",
                ["evidence", "claims"],
                "Dossier mode requires user-dossier evidence claims.",
            )
        )

    explicit_identity_values = {
        _normalize_identity_text(value)
        for value in (
            request.get("display_name"),
            *_string_items(request.get("user_constraints")),
            *(
                item.get("content")
                for item in inputs
                if isinstance(item, Mapping)
                and item.get("type") == "user_override"
            ),
        )
        if isinstance(value, str)
    }
    normalized_dossier_statements = (
        _normalize_identity_text(claim["statement"])
        for claim in dossier_claims
    )
    dossier_statements = {
        statement
        for statement in normalized_dossier_statements
        if statement not in explicit_identity_values
    }
    identity = source.get("identity")
    if not isinstance(identity, Mapping):
        return
    for path, value in _string_leaves(identity, ["identity"]):
        if _normalize_identity_text(value) in dossier_statements:
            findings.append(
                _finding(
                    "AUTHORING_IDENTITY_PROVENANCE_COLLAPSE",
                    path,
                    "Dossier evidence cannot become immutable identity without "
                    "explicit input.",
                )
            )


def _string_leaves(
    value: Any, path: list[str | int]
) -> list[tuple[list[str | int], str]]:
    if isinstance(value, str):
        return [(path, value)]
    if isinstance(value, Mapping):
        leaves: list[tuple[list[str | int], str]] = []
        for key in sorted(value):
            if isinstance(key, str):
                leaves.extend(_string_leaves(value[key], [*path, key]))
        return leaves
    if isinstance(value, list):
        leaves = []
        for index, item in enumerate(value):
            leaves.extend(_string_leaves(item, [*path, index]))
        return leaves
    return []


def _string_items(value: Any) -> list[str]:
    if not isinstance(value, list):
        return []
    return [item for item in value if isinstance(item, str)]


def _mapping_count(value: Any, member: str) -> int:
    if not isinstance(value, Mapping):
        return 0
    items = value.get(member)
    return len(items) if isinstance(items, Mapping) else 0


def _report_artifact_id(request: Mapping[str, Any]) -> str:
    readable = f"{request['namespace']}/{request['character_id']}/build-validation"
    if len(readable) <= 128:
        return readable
    identity = (
        f"{request['namespace']}/{request['character_id']}/"
        f"{request['character_version']}"
    )
    digest = hashlib.sha256(identity.encode("utf-8")).hexdigest()
    return f"build-validation/{digest}"


def _normalize_source_label(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    return "_".join(
        value.casefold().replace("-", " ").replace("_", " ").split()
    )


def _normalize_identity_text(value: str) -> str:
    normalized = " ".join(
        unicodedata.normalize("NFKC", value).casefold().split()
    )
    start = 0
    end = len(normalized)
    while start < end and unicodedata.category(normalized[start]).startswith("P"):
        start += 1
    while end > start and unicodedata.category(normalized[end - 1]).startswith("P"):
        end -= 1
    return normalized[start:end].strip()


def _finding(
    code: str, path: list[str | int], message: str
) -> dict[str, Any]:
    return {"code": code, "path": path, "message": message}


def _finding_sort_key(finding: Mapping[str, Any]) -> tuple[str, str, str]:
    return (
        str(finding["code"]),
        json.dumps(finding["path"], ensure_ascii=False, separators=(",", ":")),
        str(finding["message"]),
    )

"""Deterministic metadata for private, inactive character drafts."""

from __future__ import annotations

from hashlib import sha256
import json
from typing import Any

from kokoroarc import __version__
from kokoroarc.packs.compiler import canonical_bytes


_SOURCE_HASH_ID_PREFIX_LENGTH = 16


def build_character_draft(
    request: dict[str, Any],
    source: dict[str, Any],
    report: dict[str, Any],
) -> dict[str, Any]:
    """Build byte-stable draft metadata without mutating its inputs.

    ``source_pack_hash`` is deliberately the hash of the canonical assembled
    source object, not a hash of the source directory's serialization.
    """
    request_hash = _canonical_hash(request)
    source_hash = _canonical_hash(source)
    report_hash = _canonical_hash(report)
    artifact_id = (
        f"{request['namespace']}/{request['character_id']}/draft/"
        f"{source_hash[:_SOURCE_HASH_ID_PREFIX_LENGTH]}"
    )
    return {
        "schema_version": "1.0",
        "artifact_id": artifact_id,
        "created_by": {"component": "kokoroarc", "version": __version__},
        "build_status": "draft",
        "visibility": "private",
        "activation_allowed": False,
        "mode": request["mode"],
        "namespace": request["namespace"],
        "character_id": request["character_id"],
        "display_name": request["display_name"],
        "character_version": request["character_version"],
        "request_hash": request_hash,
        "source_pack_hash": source_hash,
        "validation_report_hash": report_hash,
        "bundle_references": {
            "request": "request.json",
            "source_pack": "source-pack",
            "validation_report": "validation-report.json",
        },
        "locale_coverage": _canonical_clone(report["locale_coverage"]),
        "provenance_counts": _canonical_clone(report["provenance_counts"]),
        "unresolved_warnings": sorted(
            {
                finding["code"]
                for finding in report.get("advisory_findings", [])
            }
        ),
    }


def _canonical_hash(value: Any) -> str:
    return sha256(canonical_bytes(value)).hexdigest()


def _canonical_clone(value: Any) -> Any:
    return json.loads(canonical_bytes(value))

from __future__ import annotations

from pathlib import Path, PurePosixPath, PureWindowsPath
import re
from typing import Any, cast

import yaml
from yaml.constructor import ConstructorError

from kokoroarc.errors import KokoroError
from kokoroarc.packs.security import PackLimits, scan_pack
from kokoroarc.schemas import SchemaRegistry


_REFERENCE_SECTIONS = ("files", "locale_files", "scenario_files")
_REQUIRED_COMPONENTS = frozenset(
    {
        "identity",
        "evidence",
        "derived_profile",
        "overrides",
        "behavior",
        "growth",
        "expressions",
    }
)
_REQUIRED_LOCALES = frozenset({"zh-CN", "en-US", "ja-JP"})
_SCENARIO_NAME_PATTERN = re.compile(r"[a-z][a-z0-9]*(?:_[a-z0-9]+)*")
_WINDOWS_ILLEGAL_CHARACTERS = frozenset('*?"<>|')
_WINDOWS_RESERVED_NAMES = frozenset(
    {
        "con",
        "prn",
        "aux",
        "nul",
        "conin$",
        "conout$",
        *(f"com{digit}" for digit in "123456789¹²³"),
        *(f"lpt{digit}" for digit in "123456789¹²³"),
    }
)


class _UniqueKeySafeLoader(yaml.SafeLoader):
    pass


def _construct_unique_mapping(
    loader: _UniqueKeySafeLoader, node: yaml.MappingNode, deep: bool = False
) -> dict[Any, Any]:
    mapping: dict[Any, Any] = {}
    for key_node, value_node in node.value:
        if key_node.tag == "tag:yaml.org,2002:merge":
            raise ConstructorError(
                None, None, "mapping merge keys are disabled", key_node.start_mark
            )
        key = loader.construct_object(key_node, deep=deep)
        try:
            duplicate = key in mapping
        except TypeError as error:
            raise ConstructorError(
                None, None, "mapping key is not hashable", key_node.start_mark
            ) from error
        if duplicate:
            raise ConstructorError(
                None, None, "duplicate mapping key", key_node.start_mark
            )
        mapping[key] = loader.construct_object(value_node, deep=deep)
    return mapping


_UniqueKeySafeLoader.add_constructor(
    yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,
    _construct_unique_mapping,
)


def resolve_pack_file(root: Path, relative: str) -> Path:
    if not isinstance(relative, str) or not relative:
        raise _unsafe_pack_path("reference must be a non-empty string")

    posix_path = PurePosixPath(relative)
    windows_path = PureWindowsPath(relative)
    if (
        "\\" in relative
        or ":" in relative
        or posix_path.is_absolute()
        or windows_path.drive
        or windows_path.root
        or ".." in posix_path.parts
        or any(_is_unsafe_windows_component(part) for part in posix_path.parts)
        or not relative.endswith((".yaml", ".yml"))
    ):
        raise _unsafe_pack_path("reference is not a pack-relative YAML path")

    try:
        resolved_root = root.resolve(strict=True)
        resolved = (resolved_root / relative).resolve(strict=False)
    except (OSError, RuntimeError, ValueError) as error:
        raise _unsafe_pack_path("reference could not be canonicalized") from error
    if not resolved.is_relative_to(resolved_root):
        raise _unsafe_pack_path("reference escapes the pack root")
    return resolved


def _is_unsafe_windows_component(component: str) -> bool:
    if component.endswith((" ", ".")) or any(
        character in _WINDOWS_ILLEGAL_CHARACTERS or ord(character) < 32
        for character in component
    ):
        return True
    device_name = component.split(".", 1)[0].rstrip(" ").casefold()
    return device_name in _WINDOWS_RESERVED_NAMES


def load_yaml(path: Path) -> dict[str, Any]:
    try:
        contents = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as error:
        raise _invalid_pack_data(
            "YAML file could not be read.", "read_failed"
        ) from error

    loader: _UniqueKeySafeLoader | None = None
    try:
        _reject_alias_events(contents)
        loader = _UniqueKeySafeLoader(contents)
        document = loader.get_single_data()
    except (RecursionError, yaml.YAMLError) as error:
        raise _invalid_pack_data("YAML document is invalid.", "invalid_yaml") from error
    finally:
        if loader is not None:
            loader.dispose()

    if not isinstance(document, dict):
        raise _invalid_pack_data(
            "YAML document must contain a mapping.", "root_not_mapping"
        )
    return cast(dict[str, Any], document)


def _reject_alias_events(contents: str) -> None:
    events = yaml.parse(contents, Loader=yaml.SafeLoader)
    try:
        for event in events:
            if isinstance(event, yaml.events.AliasEvent):
                raise ConstructorError(
                    None, None, "YAML aliases are disabled", event.start_mark
                )
    finally:
        events.close()


def load_source_pack(root: Path, schemas: SchemaRegistry) -> dict[str, Any]:
    scanned_files = frozenset(scan_pack(root, PackLimits()))
    manifest_path = resolve_pack_file(root, "character.yaml")
    if manifest_path not in scanned_files:
        raise _invalid_pack_data(
            "Character pack reference was not found.", "unscanned_reference"
        )
    manifest = load_yaml(manifest_path)
    if any(not isinstance(key, str) for key in manifest):
        raise _invalid_pack_data(
            "Character pack manifest is invalid.", "invalid_manifest_key"
        )

    references = {
        section: _manifest_reference_items(manifest, section)
        for section in _REFERENCE_SECTIONS
    }
    _validate_reference_names(references)
    resolved_references = _resolve_reference_paths(
        root, references, scanned_files, manifest_path
    )
    assembled = {
        key: manifest[key]
        for key in sorted(manifest)
        if key not in _REFERENCE_SECTIONS
    }
    for component, path in resolved_references["files"]:
        assembled[component] = load_yaml(path)
    assembled["locales"] = {
        locale: load_yaml(path)
        for locale, path in resolved_references["locale_files"]
    }
    assembled["scenarios"] = {
        scenario: load_yaml(path)
        for scenario, path in resolved_references["scenario_files"]
    }
    schemas.validate("character-source", assembled)
    return assembled


def _manifest_reference_items(
    manifest: dict[str, Any], section: str
) -> list[tuple[str, str]]:
    references = manifest.get(section)
    if not isinstance(references, dict):
        raise _invalid_pack_data(
            "Character pack manifest is invalid.", "invalid_reference_map"
        )
    if any(not isinstance(key, str) for key in references):
        raise _invalid_pack_data(
            "Character pack manifest is invalid.", "invalid_reference_name"
        )
    if any(not isinstance(reference, str) for reference in references.values()):
        raise _invalid_pack_data(
            "Character pack manifest is invalid.", "invalid_reference_value"
        )
    return sorted(references.items())


def _validate_reference_names(
    references: dict[str, list[tuple[str, str]]],
) -> None:
    component_names = {name for name, _relative in references["files"]}
    locale_names = {name for name, _relative in references["locale_files"]}
    scenario_names = {name for name, _relative in references["scenario_files"]}
    if component_names != _REQUIRED_COMPONENTS:
        raise _invalid_pack_data(
            "Character pack manifest is invalid.", "invalid_component_names"
        )
    if locale_names != _REQUIRED_LOCALES:
        raise _invalid_pack_data(
            "Character pack manifest is invalid.", "invalid_locale_names"
        )
    if (
        not 1 <= len(scenario_names) <= 128
        or any(len(name) > 128 for name in scenario_names)
        or any(
            _SCENARIO_NAME_PATTERN.fullmatch(name) is None
            for name in scenario_names
        )
    ):
        raise _invalid_pack_data(
            "Character pack manifest is invalid.", "invalid_scenario_names"
        )


def _resolve_reference_paths(
    root: Path,
    references: dict[str, list[tuple[str, str]]],
    scanned_files: frozenset[Path],
    manifest_path: Path,
) -> dict[str, list[tuple[str, Path]]]:
    resolved_references: dict[str, list[tuple[str, Path]]] = {
        section: [] for section in _REFERENCE_SECTIONS
    }
    used_paths = {manifest_path}
    for section in _REFERENCE_SECTIONS:
        for name, relative in references[section]:
            path = resolve_pack_file(root, relative)
            if path in used_paths:
                raise _invalid_pack_data(
                    "Character pack references must be independent.",
                    "duplicate_reference",
                )
            used_paths.add(path)
            resolved_references[section].append((name, path))
    for section in _REFERENCE_SECTIONS:
        for _name, path in resolved_references[section]:
            if path not in scanned_files:
                raise _invalid_pack_data(
                    "Character pack reference was not found.",
                    "unscanned_reference",
                )
    return resolved_references


def _unsafe_pack_path(reason: str) -> KokoroError:
    return KokoroError(
        "UNSAFE_PACK_PATH",
        "Character pack reference is unsafe.",
        details={"reason": reason},
    )


def _invalid_pack_data(message: str, reason: str) -> KokoroError:
    return KokoroError(
        "INVALID_PACK_DATA",
        message,
        details={"reason": reason},
    )

